package com.aierp.schedule;
import java.util.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType;
public interface ScheduleSavedViewRepository extends JpaRepository<ScheduleSavedViewEntity,UUID> { List<ScheduleSavedViewEntity> findByProjectId(UUID projectId); Optional<ScheduleSavedViewEntity> findByIdAndProjectId(UUID id,UUID projectId); long countByProjectIdAndScope(UUID projectId,ScheduleSavedViewEntity.Scope scope); long countByProjectIdAndScopeAndOwnerId(UUID projectId,ScheduleSavedViewEntity.Scope scope,UUID ownerId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select v from ScheduleSavedViewEntity v where v.id=:id and v.projectId=:projectId") Optional<ScheduleSavedViewEntity> lockByIdAndProjectId(UUID id,UUID projectId); }
